 *
 * ELF version script for libnsgai.so.
 *
 * Exports only the documented public API (the `nsgai_*` family plus
 * the weak POSIX-named aliases that allow a direct link to replace
 * libc's resolver).  All other symbols - the internal `nsgai_channel_*`
 * helpers, `nsgai_ns_resolve_*`, `nsgai_map_ai_flags`, `cb_asocket`,
 * etc. - become local and are not visible to consumers, so they
 * cannot accidentally be relied upon and we are free to refactor them
 * without an ABI bump.
 *
 * Wired in via target_link_options() in CMakeLists.txt.  A future
 * second version (NSGAI_1) can be added for additions without
 * bumping SONAME.
 */

NSGAI_0 {
    global:
        /* Implicit + explicit nsgai_* entry points and helpers. */
        nsgai_getaddrinfo;
        nsgai_getaddrinfo_ns;
        nsgai_getaddrinfo_nsfd;
        nsgai_getaddrinfo_a;
        nsgai_getaddrinfo_a_ns;
        nsgai_getaddrinfo_a_nsfd;
        nsgai_getnameinfo;
        nsgai_getnameinfo_ns;
        nsgai_getnameinfo_nsfd;
        nsgai_freeaddrinfo;
        nsgai_gai_strerror;
        nsgai_suspend;
        nsgai_error;
        nsgai_cancel;

        /* Weak POSIX-named aliases - linking libnsgai replaces libc. */
        getaddrinfo;
        getaddrinfo_a;
        getnameinfo;
        freeaddrinfo;
        gai_strerror;
        gai_suspend;
        gai_error;
        gai_cancel;

    local:
        *;
};
